// function isComputerNameValid(payload) {
//     for (var i = 0; i < payload.items.length; i++)
//         if (payload.items[i].className == 'cmdb_ci_computer' && payload.items[i].values.name.startsWith('TEST-'))
//             return false;
//     return true;
// }
/**
 * The following properties/functions are available for all parameters of type 'Array' inside the IRE payload e.g. items, relations, referenceItems, lookup and related:
 * length - Returns the number of elements in an array
 * push() - Add an item to the end of an array
 * pop() - Remove an item from the end of an array
 * shift() - Remove an item from the beginning of an array
 * unshift() - Add an item to the beginning of an array
 *
 * Important points:
 * 1) The before script is executed once per batch and not per payload. The input array elements contain all the payloads for a given batch.
 * 2) Each element in the array has only 3 fields i.e. status, reason, and payload. Adding additional fields to the array elements might result in unexpected errors.
 * 3) The 'status' can be set to 'SKIPPED' in order to skip a payload in this batch from further processing. Setting 'status' to any other value will be ignored by the RTE processor.
 * 4) Optionally, a 'reason' can be set for skipping the payload. This will be the message on the import set run for this particular row.
 * 5) To match the batch size after script execution, only the length property is available for input array e.g. input.length 
 * 6) Using any of the above functions e.g. push(), pop(), shift() and unshift() on input array directly will result in unexpected errors.
 *
 * Below is an example of an IRE input payload. There can be more fields/parameters depending on each use case. Refer to the ServiceNow Product Documentation for more examples on the IRE payload.
 * {
 *  'items': [
 *    {
 *      'className': 'cmdb_ci_computer',
 *      'values': {
 *        'name': 'Macbook Pro 15',
 *        'os_version': '5.1.2600',
 *        'ram': '2048',
 *        'disk_space': '1024'
 *      }
 *    }
 *  ]
 * }
 */

(function (input, runId) {

	//This function will take the IRE input and pre-process all of the batched items using the IdentifyCIEnhanced API allowing for to option to ignore or skip unwanted inserts / updates knowing what the end result will be with the IRE.
	//
	var strInput = input + "";

	var inputCopy = JSON.parse(strInput);
	//Concatenate all of the payloads from input into a single payload. This way we are only needing to submit a call to the IRE per batch.
	var concatPayload = {
		items: [],
		relations: [],
		referenceItems: []
	};
	var indexTrackerDictionary = {};
	inputCopy.forEach((row, r) => {
		row.payload.items.forEach((item, i) => {
			concatPayload.items.push(item);
			indexTrackerDictionary[concatPayload.items.length - 1] = {
				"mainIndex": r,
				"subIndex": i
			};
		});
		if(concatPayload.relations && concatPayload.relations.length > 0){
			concatPayload.relations = concatPayload.relations.concat(row.payload.relations);
		}
		if(concatPayload.referenceItems && concatPayload.referenceItems.length > 0){
			concatPayload.referenceItems = concatPayload.referenceItems.concat(row.payload.referenceItems);
		}
	});


	//Defaults
	var options = {
		"deduplicate_payloads": true,
		"generate_summary": false,
		"partial_commits": true,
		"partial_payloads": true,
		"skip_updating_last_scan_to_now": false,
		"skip_updating_source_last_discovered_to_now": false
	};
	var concatPayloadStr = JSON.stringify(concatPayload);
	var output = sn_cmdb.IdentificationEngine.identifyCIEnhanced("SG-example", concatPayloadStr, options);
	if (!gs.nil(output)) {
		var outputObj = JSON.parse(output);
		outputObj.items.forEach(outputItem => {

			var inputIndices = outputItem.inputIndices;
			var operation = outputItem.operation;
			var className = outputItem.className;
			var sysId = outputItem.sysId;
			inputIndices.forEach(inputIndex => {
				if (concatPayload.items[inputIndex]) {
					var inputItem = concatPayload.items[inputIndex];
					if (gs.nil(inputItem.x_ire_identify_ci_output)) {
						inputItem.x_ire_identify_ci_output = {};
						inputItem.x_ire_identify_ci_output.inputIndices = [];
					}
					inputItem.x_ire_identify_ci_output.operation = operation;
					inputItem.x_ire_identify_ci_output.sysId = sysId;
					inputItem.x_ire_identify_ci_output.className = className;
					inputItem.x_ire_identify_ci_output.inputIndices = inputIndices;
				}
			});
		});
	}

	//Loop over array backwards as to not affect the index order which is tracked in a separate dictionary object.
	for (var i = concatPayload.items.length - 1; i >= 0; i--) {
		var item = concatPayload.items[i];
		if (
			item.x_ire_identify_ci_output &&
			item.x_ire_identify_ci_output.operation.indexOf("INSERT") > -1
		) {
			var indexInfo = indexTrackerDictionary[i];
			var rowIndex = indexInfo.mainIndex;
			var itemIndex = indexInfo.subIndex;
			if (input[rowIndex].payload.items[itemIndex]) {
				var internalId = item.internal_id; 
				//Mark ALL items realted to this item for removal which will be done later.
				//markItemsForRemoval(internalId, input[rowIndex].payload.items);
			}
		}
	}

	for (var r = input.length - 1; r >= 0; r--) {
		var row = input[r];
		var payload = row.payload;
		cleanseItems(payload.items, (function(item){
			if (item.values && item.values.x_marked_for_removal) {
				var internalId = item.internal_id;
				cleanseItems(payload.relations, (function(relationItem, id){
					return (relationItem.parent_id == id || relationItem.child_id == id);
				}), internalId);
				cleanseItems(payload.referenceItems, (function(referenceItem, id){
					return (referenceItem.referenced == id || referenceItem.referencedBy == id);
				}), internalId);
				return true;
			}else{
				return false;
			}
		}));
		//If a row has all ignored items, set the row to skipped to prevent errors
		if (payload.items.length < 1) {
			row.status = "SKIPPED";
			row.reason = "Skipping because no items in the row were valid.";
		}
	}
})(input, runId);


function cleanseItems(arr, callback, optionalId){
	var i = arr.length - 1;
	while (i >= 0) {
		var item = arr[i];
		if(callback(item, optionalId)){
			for (var j = i; j < arr.length - 1; j++) {
				arr[j] = arr[j + 1];
			}
			arr.pop(); // Remove the last item
		}
		i--;
	}
}


//Marks all items that are equial to or are sourced from an internal ID as marked for removal.
function markItemsForRemoval(internalId, items){
	if(gs.nil(items)){
		return;
	}
	for(var i = 0; i < items.length; i++){
		var item = items[i];
		if(item.internal_id == internalId || item.internal_id.startsWith(internalId + "|||")){
			item.values.x_marked_for_removal = true;
		}
	}
}
